package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import app.layan.quran.*;import org.json.*;import java.io.*;
public final class UniformFontRegression extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private int checks;private void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();QiraatData.directory(c).mkdirs();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",false).putBoolean("useArabicNames",true).commit();JSONArray all=QiraatData.catalog(c).getJSONArray("riwayat");float common=-1;StringBuilder records=new StringBuilder();
 for(int i=0;i<all.length();i++){String id=all.getJSONObject(i).getString("id");JSONObject m=QiraatData.metadata(c,id);if(!QiraatData.downloaded(c,id)){String url=m.getString("url");QiraatDownload.install(new File("/data/local/tmp/qiraat-corpus",url.substring(url.lastIndexOf('/')+1)),QiraatData.directory(c),id,m.getLong("bytes"),m.getString("sha256"),(p,s)->{});}
 QiraatReaderActivity a=(QiraatReaderActivity)startActivitySync(new Intent(c,QiraatReaderActivity.class).putExtra("riwayah",id).putExtra("page",300).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=SystemClock.elapsedRealtime()+120000;boolean ok=false;while(SystemClock.elapsedRealtime()<end){boolean[] ready={false};runOnMainSync(()->ready[0]=a.currentPageReady());if(ready[0]){ok=true;break;}SystemClock.sleep(100);}check(ok,"Loaded source page "+id);waitForIdleSync();float[] actual={0};runOnMainSync(()->actual[0]=a.currentFontPixels());check(actual[0]>0,"Measured final typography "+id);if(common<0)common=actual[0];check(Math.abs(actual[0]-common)<.1f,"Same final font size "+id+" "+actual[0]+" vs "+common);records.append(id+"="+actual[0]+"px\n");
 if(id.equals("hafs")||id.equals("warsh")||id.equals("ibn-wardan")||id.equals("ruways")||id.equals("idris")){Bitmap shot=NativeScreens.capture(this,a);File dir=c.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream o=new FileOutputStream(new File(dir,"font-final-"+id+".png"))){shot.compress(Bitmap.CompressFormat.PNG,100,o);}shot.recycle();}runOnMainSync(a::finish);waitForIdleSync();}
 result.putString("result","PASS "+checks+" checks; all twenty final native font scales within 0.1px\n"+records);finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}